import java.lang.management.ManagementFactory;
import java.lang.management.MemoryPoolMXBean;
import java.lang.management.MemoryUsage;
import java.lang.reflect.Field;
import java.util.Map;
import java.util.Set;
import java.util.stream.Collectors;

public class Main {
    static class Example {
        static String staticField = "static-value";
        static final int COMPILE_TIME_CONSTANT = 100;
        void method() {}
    }

    static Map<String, MemoryUsage> poolUsages() {
        return ManagementFactory.getMemoryPoolMXBeans().stream()
            .collect(Collectors.toMap(MemoryPoolMXBean::getName, MemoryPoolMXBean::getUsage));
    }

    public static void main(String[] args) throws Exception {
        Map<String, MemoryUsage> pools = poolUsages();
        Set<String> names = pools.keySet();
        long metaspaceUsed = pools.entrySet().stream()
            .filter(e -> e.getKey().contains("Metaspace"))
            .mapToLong(e -> e.getValue().getUsed())
            .sum();
        long codeHeapUsed = pools.entrySet().stream()
            .filter(e -> e.getKey().contains("CodeHeap") || e.getKey().contains("Code Cache"))
            .mapToLong(e -> e.getValue().getUsed())
            .sum();

        Class<?> clazz = Example.class;
        Field field = clazz.getDeclaredField("staticField");
        String staticValue = (String) field.get(null);
        String heapString = new String("meta");
        String interned = heapString.intern();

        System.out.println("pools: " + names);
        System.out.println("metaspace/code used: " + metaspaceUsed + "/" + codeHeapUsed);
        System.out.println("class loader: " + clazz.getClassLoader());
        System.out.println("static field: " + staticValue + ", interned same as literal: " + (interned == "meta"));

        assert names.stream().anyMatch(name -> name.contains("Metaspace"));
        assert names.stream().anyMatch(name -> name.contains("CodeHeap") || name.contains("Code Cache"));
        assert metaspaceUsed > 0;
        assert codeHeapUsed > 0;
        assert staticValue.equals("static-value");
        assert Example.COMPILE_TIME_CONSTANT == 100;
        assert interned == "meta";
        assert heapString != "meta";
    }
}
